// GENERATED BY http-utils-split script — do not edit manually.
// Behavior-preserving extraction from http-utils.js.

const {
  ZCODE_PLAN_BALANCE_URL,
  ZCODE_OAUTH_MODELS_BASE_URL,
  resolveProviderApiBaseUrl
} = require('../account/provider-api-base-url');
const {
  readResponseJson,
  readResponseText,
  sanitizeResponseText
} = require('./response-body');
const { fetchWithTimeout } = require('./http-utils-utils');
const { inferProviderFromModel } = require('./providers');

// 只暴露网关能路由回 zcode 的模型 ID（glm*/zcode* 裸命名空间）。coding 目录与
// balance capabilities 还含 opencode-go/*、cline-free/* 等伙伴命名空间：bigmodel
// 推理端点不认它们（实测 400「modelCode 不存在」），而网关按前缀/可用性会把这
// 类 ID 路由到 opencode，造成跨 provider 误路由与误计费。判定复用路由器的
// inferProviderFromModel，保证「暴露即路由回 zcode」以路由规则为单一事实来源。
function isZcodeRoutableModelId(modelId) {
  return inferProviderFromModel(modelId) === 'zcode';
}

function resolveFetcher(options) {
  return (options && typeof options.fetchWithTimeout === 'function')
    ? options.fetchWithTimeout
    : fetchWithTimeout;
}

async function fetchZcodePlanBalanceModels(options, account, timeoutMs) {
  const jwtToken = String(account && account.zcodeJwtToken || '').trim();
  if (!jwtToken) return null;
  let res;
  try {
    res = await resolveFetcher(options)(ZCODE_PLAN_BALANCE_URL, {
      method: 'GET',
      headers: { authorization: `Bearer ${jwtToken}` }
    }, timeoutMs, {
      proxyUrl: options && options.proxyUrl,
      noProxy: options && options.noProxy
    });
  } catch {
    return null;
  }
  if (!res.ok) return null;
  const json = await readResponseJson(res).catch(() => null);
  if (!json || typeof json !== 'object') return null;
  // zcode 业务错误是 HTTP 200 + {code!=0, success:false}，视为失败以回退 paas 探测。
  if (json.success === false) return null;
  if (json.code !== undefined && json.code !== 0 && json.code !== 200 && json.code !== '0' && json.code !== '200') return null;
  const balances = json.data && Array.isArray(json.data.balances) ? json.data.balances : null;
  if (!balances) return null;
  // 与桌面端 resolveZaiStartPlanBalanceModelIds 对齐：capabilities 的 model:* 优先，
  // 没有则用 show_name；大小写不敏感去重。空数组也是有效结果（套餐确实无模型），
  // 不回退——否则会落到必然 401 的 paas 探测。
  const seen = new Set();
  const models = [];
  for (const balance of balances) {
    const capabilities = Array.isArray(balance && balance.capabilities) ? balance.capabilities : [];
    const capabilityModels = capabilities
      .map((cap) => String(cap || '').trim())
      .filter((cap) => cap.toLowerCase().startsWith('model:'))
      .map((cap) => cap.slice('model:'.length).trim())
      .filter(Boolean);
    const candidates = capabilityModels.length > 0
      ? capabilityModels
      : [String(balance && balance.show_name || '').trim()];
    for (const id of candidates) {
      if (!id) continue;
      if (!isZcodeRoutableModelId(id)) continue;
      const key = id.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      models.push(id);
    }
  }
  return models;
}

// balance 接口不可用时的回退探测：GET ZCODE_OAUTH_MODELS_BASE_URL/models，
// Bearer 为 zai accessToken（会过期且无 refresh token，过期后实测 401，此时抛错
// 由上层按探测失败处理）。zcode OAuth 账号的 openaiBaseUrl 已指向推理端点
//（…/zcode-plan/anthropic），绝不能 fall through 到下方通用探测拼出错误 URL。

// 账号缺少 zcodeJwtToken 时不再回退 paas 探测：此时唯一的回退凭据 zai
// accessToken 必然已过期且无 refresh，探测只会把原始 HTTP 401 抛给 WebUI。
// 改为抛出可识别的定向错误（code=zcode_jwt_missing_relogin），accounts 视图
// 据此提示「需要重新登录」而不是展示上游 401。
function createZcodeJwtMissingError() {
  const err = new Error('zcode_jwt_missing_relogin：ZCode 登录凭据缺失，需要重新登录');
  err.code = 'zcode_jwt_missing_relogin';
  err.reloginRequired = true;
  return err;
}

async function fetchZcodePaasModels(options, account, timeoutMs) {
  const accessToken = String(account && account.accessToken || '').trim();
  if (!accessToken) throw new Error('zcode_oauth_access_token_missing');
  const res = await resolveFetcher(options)(`${ZCODE_OAUTH_MODELS_BASE_URL}/models`, {
    method: 'GET',
    headers: { authorization: `Bearer ${accessToken}` }
  }, timeoutMs, {
    proxyUrl: options && options.proxyUrl,
    noProxy: options && options.noProxy
  });
  if (!res.ok) {
    const text = await readResponseText(res).catch(() => '');
    const err = new Error(`HTTP ${res.status} ${sanitizeResponseText(text, 160)}`.trim());
    err.status = res.status;
    throw err;
  }
  const json = await readResponseJson(res);
  if (json && json.success === false) {
    throw new Error(String(`${json.code ? json.code + ' ' : ''}${json.msg || 'models_error'}`).trim());
  }
  if (!Array.isArray(json && json.data)) {
    throw new Error('models_response_missing_data');
  }
  return json.data
    .map((x) => String((x && x.id) || '').trim())
    .filter(Boolean)
    .filter(isZcodeRoutableModelId);
}


module.exports = { createZcodeJwtMissingError, fetchZcodePlanBalanceModels, fetchZcodePaasModels, isZcodeRoutableModelId };
